/* mini hourly heat for one rota and tier */
function heat(R,tier,w0,o){o=o||{};const g=grid(R,tier,w0);let h=`<div class="oc-heat ${o.mini?"mini":""}" role="grid" aria-label="${E(R.n)} ${tier} coverage, hour by day"><div class="oc-hh"><span></span>${Array.from({length:24},(_,i)=>`<span>${i%3===0?z2(i):""}</span>`).join("")}</div>`;
 for(let d=0;d<7;d++){const t0=w0+d*DAY;h+=`<div class="oc-hr"><span class="oc-dl">${DN[(d+1)%7]}<small>${fd(t0)}</small></span>${Array.from({length:24},(_,i)=>{const c=g[d*24+i],st=ST[c.s];const who_=c.p.map(x=>x.who).join(", ")||"nobody";const ttl=`${DN[(d+1)%7]} ${fh(i)}: needs ${c.need}, effective ${U.esc(c.n)}. ${st[1]}. On call: ${who_}${c.pend?". A scheduled person has pending time off.":""}`;return `<button type="button" class="oc-c ${st[0]}${c.pend?" pend":""}${c.t<=NOW&&NOW<c.t+HR?" now":""}" data-oc-cell="${R.id}|${tier}|${U.esc(c.t)}" title="${E(ttl)}" aria-label="${E(ttl)}">${o.mini?"":(c.need?c.n:"")}</button>`}).join("")}</div>`}
 return h+"</div>"}
/* portfolio heat: share of required slots covered, across all rotas */
