function ruleMatch(r,s){const w=r.when,sv=svcOf(s.svc);if(w.prio.length&&!w.prio.includes(s.prio))return false;if(w.tier&&(!sv||sv.tier!==w.tier))return false;if(w.svc.length&&!w.svc.includes(s.svc))return false;if(w.lang&&w.lang!==s.lang)return false;return true}
