function shiftIdx(){const k=OC.ver+"|"+DIR.length+"|"+SCALE.on+"|"+rotas().length;if(shiftC.k===k)return shiftC.m;const m=new Map();const s0=d0(NOW),n=14*24;rotas().forEach(R=>{TIERS.forEach(tier=>{if(!R.layers.some(L=>L.tier===tier)&&!OC.ov.some(o=>o.rota===R.id&&o.tier===tier))return;const open={};for(let i=0;i<=n;i++){const t=s0+i*HR;const cur=i<n?at(R,tier,t).map(x=>x.who):[];Object.keys(open).forEach(w=>{if(!cur.includes(w)){const o=open[w];(m.get(w)||m.set(w,[]).get(w)).push({R,tier,from:o,to:t});delete open[w]}});cur.forEach(w=>{if(open[w]==null)open[w]=t})}})});shiftC={k,m};return m}
const shiftsOf=n=>(shiftIdx().get(n)||[]).slice().sort((a,b)=>a.from-b.from);
WORK.push({kind:"On-call shifts",tag:"ONCALL",fn:n=>shiftsOf(n).slice(0,8).map(s=>{const h=Math.round((s.to-s.from)/HR);const ptoc=ptoHit(n,s.from)||ptoHit(n,s.to-HR);return {id:s.R.id+"-"+s.tier[0]+"-"+fd(s.from).replace(" ",""),t:s.R.n+": "+s.tier,sub:fdw(s.from)+" "+fh(new Date(s.from).getUTCHours())+" to "+fdw(s.to)+" "+fh(new Date(s.to).getUTCHours())+" ("+(h>=48?Math.round(h/24)+" days":h+" h")+")"+(ptoc?" · time off in this shift":""),due:fd(s.from),st:ptoc?"bad":s.from<=NOW?"good":"info",hrs:Math.min(6,Math.round(h*.04)),go:()=>go("svc_oncall")}})});
