 if(v.ai){R.ai=R.ai||{agent:"Triage Agent",afterMin:2,guards:["Acts on P3 and P4 only","Cannot restart or change anything","Pages a human for P1 and P2"]};if(!R.layers.some(L=>L.tier==="First responder"&&L.who==="Triage Agent"))R.layers.push(Object.assign(fix("First responder","AI first responder","Triage Agent"),{auto:1}))}else{R.ai=null;R.layers=R.layers.filter(L=>!(L.tier==="First responder"&&L.who==="Triage Agent"))}
