 return card("Skill gap analysis","For each skill a rota needs: how many people on that rota are qualified (level 3 or higher, not expired), how many exist company-wide, and what to do about it.",`<div class="row" style="margin-bottom:10px"><span class="pill ${d.pct>=90?"good":d.pct>=70?"warn":"bad"}">Depth ${d.pct}%</span><span class="pill ${d.spof?"bad":"good"}">${d.spof} single points of failure</span>${fchip("m_skill_depth")}</div>`+btHTML({id:"sk_gap",h:440,rowH:56,key:"k",facets:["status","tier"],exportName:"skill-gaps",cols:[{k:"rota",label:"Rota",wrap:1,fmt:r=>`<b>${E(r.R.n)}</b><div class="muted small">${r.R.tier}</div>`,val:r=>r.R.n},{k:"tier",label:"Tier",val:r=>r.R.tier},{k:"skill",label:"Skill needed",fmt:r=>E((skillById(r.sid)||{n:r.sid}).n),val:r=>(skillById(r.sid)||{n:r.sid}).n},{k:"on",label:"Qualified on rota",fmt:r=>`<span class="num">${r.on}</span> of ${r.need}`,val:r=>r.on},{k:"names",label:"Who",wrap:1,fmt:r=>r.names.slice(0,4).map(n=>sav(n,20)).join(" ")||'<em class="oc-none">Nobody</em>',val:r=>r.names.join(", ")},{k:"comp",label:"Qualified company-wide",fmt:r=>`<span class="num">${r.comp}</span>`,val:r=>r.comp},{k:"status",label:"Status",fmt:r=>`<span class="pill ${r.ok?"good":r.spof?"bad":"warn"}">${r.ok?"Enough":r.spof?"Single point of failure":"Thin"}</span>`,val:r=>r.ok?"Enough":r.spof?"Single point of failure":"Thin"},{k:"act",label:"Action",fmt:r=>r.ok?"":`<button class="btn quiet" data-sk-train="${r.R.id}|${r.sid}">Cross-train</button>`}],rows:()=>rows.map(x=>Object.assign({},x,{k:x.R.id+"|"+x.sid})),open:k=>{const [rid,sid]=k.split("|");skillDrawer(sid)}}))
