function taxPane(){return card("Skills taxonomy","Categories, skills and proficiency levels. Rotas, workflows and assignment rules pick skills from this list.",`<div class="oc-leg">${LEVELS.map(l=>`<span>${lvBar(l.n,"verified")}<b>${l.l}</b> ${E(l.d)}</span>`).join("")}</div>`+btHTML({id:"sk_tax",h:440,rowH:44,key:"id",exportName:"skills",facets:["cat"],cols:[{k:"n",label:"Skill",fmt:r=>`<b>${E(r.n)}</b>${r.cert?' <span class="pill info">Certification</span>':""}${r.auto?' <span class="pill warn">Auto-added</span>':""}`,val:r=>r.n},{k:"cat",label:"Category",val:r=>r.cat},{k:"h",label:"People",fmt:r=>`<span class="num">${SKILLSDB.holders(r.id).length}</span>`,val:r=>SKILLSDB.holders(r.id).length},{k:"q",label:"Qualified (3+)",fmt:r=>`<span class="num">${SKILLSDB.qualified(r.id,3).length}</span>`,val:r=>SKILLSDB.qualified(r.id,3).length},{k:"v",label:"Verified",fmt:r=>{const h=SKILLSDB.holders(r.id);return h.length?Math.round(h.filter(x=>x.st==="verified"||x.st==="certified").length/h.length*100)+"%":"0%"},val:r=>{const h=SKILLSDB.holders(r.id);return h.length?h.filter(x=>x.st==="verified"||x.st==="certified").length/h.length:0}},{k:"rq",label:"Required by",fmt:r=>`<span class="num">${rotas().filter(R=>rotaSkills(R).includes(r.id)).length}</span> rotas`,val:r=>rotas().filter(R=>rotaSkills(R).includes(r.id)).length}],rows:()=>allSkills(),open:id=>skillDrawer(id)}),`<div class="row"><button class="btn primary" data-sk-newskill="1">Add a skill</button></div>`)}
