DND.on("oc_swap",(id,from,to)=>{if(from===to||to==="pool")return render();const a=id.split("|");const dest=to.split("|");const R=rotaById(dest[0]);if(!R)return render();const day=wkStart()+(+dest[2])*DAY;
 if(a[0]==="P"){const nm=a[1];addOv(R,dest[1],day,day+DAY,nm,null,"Dragged from the qualified list","override");const av=AVAIL(nm,day+10*HR);toast(nm+" added to "+dest[1].toLowerCase()+" on "+fd(day)+(av.ok?"":". Warning: "+av.reason),av.ok?"good":"warn");return render()}
 const [,rid,tier,d,nm]=a;if(rid!==R.id){toast("Shifts move inside one rota. Use a swap request across rotas.","warn");return render()}const sday=wkStart()+(+d)*DAY;
 const occ=[];for(let h=0;h<24;h++)at(R,dest[1],day+h*HR).forEach(x=>{if(!occ.includes(x.who))occ.push(x.who)});const Y=occ.find(x=>x!==nm);
 if(occ.includes(nm)&&!Y){toast(nm+" is already on call that day","info");return render()}
 if(Y&&dest[1]===tier&&Y===nm)return render();
 if(Y){addOv(R,tier,sday,sday+DAY,Y,nm,"Swap with "+nm,"swap");addOv(R,dest[1],day,day+DAY,nm,Y,"Swap with "+Y,"swap");toast(nm+" and "+Y+" swapped ("+fd(sday)+" and "+fd(day)+")","good")}else{addOv(R,dest[1],day,day+DAY,nm,null,"Moved by drag","override");addOv(R,tier,sday,sday+DAY,null,nm,"Moved away by drag","override");toast(nm+" moved to "+fd(day)+". "+fd(sday)+" now has an open "+tier.toLowerCase()+" shift.","warn")}
 const pt=ptoHit(nm,day);if(pt)toast(nm+" has "+pt.type.toLowerCase()+" on "+fd(day),"warn");render()});
DND.on("oc_esc",(id,from,to,idx)=>{const p=escPolicies().find(x=>x.id===OC.escSel);const i=+id.split("|")[1];const [x]=p.lv.splice(i,1);p.lv.splice(Math.min(idx,p.lv.length),0,x);p.lv.forEach((l,k)=>{if(k===0)l.wait=0});OC.ver++;toast("Level order updated. The first level always pages at once.","good");audit("reordered escalation",p.n);render()});
DND.on("oc_rule",(id,from,to,idx)=>{const rs=rulesAll();const i=+id.split("|")[1];const [x]=rs.splice(i,1);rs.splice(Math.min(idx,rs.length),0,x);toast("Rule order updated. The first matching rule wins.","good");audit("reordered assignment rules",x.n);render()});
DND.on("sk_rota",(id,from,to)=>{if(!to||!/^rota\|/.test(to))return render();const R=rotaById(to.split("|")[1]);const nm=id.split("|")[1];if(!R)return render();const L=R.layers.find(l=>l.kind==="rot"&&l.tier==="Primary")||R.layers.find(l=>l.kind==="rot");if(!L){toast("This rota has no rotation to join","warn");return render()}if(L.members.includes(nm)){toast(nm+" is already in "+R.n,"info");return render()}L.members.push(nm);OC.ver++;GC.clear();SC.clear();audit("added to rota rotation",R.n+": "+nm);const miss=rotaSkills(R).filter(s=>SKILLSDB.level(nm,s)<3).map(s=>(skillById(s)||{n:s}).n);toast(nm+" joins "+R.n+(miss.length?". Below level 3 in "+miss.join(", "):". Meets the skill requirements."),miss.length?"warn":"good");render()});
/* person 360: skills, availability and on-call */
P360_TABS.push({label:"Skills and on-call",fn:r=>{const sk=SKILLSDB.of(r.name).slice().sort((a,b)=>b.level-a.level);const sh=shiftsOf(r.name);const days=Array.from({length:14},(_,i)=>{const t=d0(NOW)+i*DAY;const a=AVAIL(r.name,t+10*HR);const pt=ptoHit(r.name,t);return `<i class="sk-a ${pt?(pt.st==="pending"?"pend":"pto"):a.status==="holiday"?"hol":a.status==="off"?"off":"ok"} ${sh.some(s=>s.from<t+DAY&&s.to>t)?"oc":""}" title="${E(fdw(t)+": "+(pt?pt.type:a.reason))}"></i>`}).join("");
 const av=AVAIL(r.name,NOW);return `<div class="eyebrow">Right now</div><div class="row" style="margin:6px 0"><span class="pill ${av.ok?"good":"bad"}">${av.ok?"Available":E(av.reason)}</span><span class="muted small">${E(av.hours)} · ${E(av.tz)}</span></div><div class="eyebrow" style="margin-top:12px">Next 14 days</div><div class="sk-ad p360">${days}</div><p class="muted small">Green is working, red is time off, amber is pending, a dot means on call.</p><div class="eyebrow" style="margin-top:12px">On-call shifts</div>${sh.length?sh.slice(0,6).map(s=>`<div class="oc-ov"><span class="pill info">${s.tier}</span><div class="oc-attt"><b>${E(s.R.n)}</b><span class="muted small">${fdw(s.from)} to ${fdw(s.to)}</span></div></div>`).join(""):'<p class="muted">Not scheduled in the next 14 days.</p>'}<div class="eyebrow" style="margin-top:12px">Skills (${sk.length})</div><div class="row">${sk.map(skillChip).join("")||'<span class="muted">None recorded</span>'}</div><div class="row" style="margin-top:12px"><button class="btn" data-sk-claim="|${E(r.name)}">Add a skill</button></div>`}});
/* chat and search */
ASKX.push(q=>{
 if(/who('s| is| are)?.{0,12}on.?call|on.?call (now|today|tonight|this week)/i.test(q)){go("svc_oncall");const l=rotas().filter(R=>!R.gen).slice(0,6).map(R=>`${E(R.n)}: <b>${E(nowOn(R,"Primary").join(", ")||"nobody")}</b>`).join("; ");say(q,{t:`On call now (primary): ${l}. ${allStats().pct}% of required hours are covered over the next 14 days.`,steps:["Read every rota layer and override for this hour","Removed people on approved time off"]});return true}
 if(/(on.?call|rota|coverage).{0,30}(gap|hole|uncovered|short|missing)|(gap|hole).{0,20}(on.?call|rota|coverage)/i.test(q)){const g=[];rotas().forEach(R=>gapRuns(R).forEach(x=>g.push(x)));g.sort((a,b)=>(b.to-b.from)-(a.to-a.from));go("svc_oncall");S.v.svc_ocv=0;say(q,{t:g.length?`${g.length} coverage runs are short. Largest: <b>${E(rotaById(g[0].rota).n)}</b> ${g[0].tier.toLowerCase()}, ${hrsStr(g[0].to-g[0].from)} from ${fdw(g[0].from)}. The Recommendations view prices the fix.`:"Every required hour is covered for the next 14 days.",steps:["Compared required hours with scheduled people for 14 days","Subtracted approved time off"]});return true}
 let m=/who can (?:do|handle|fix|support|work on|help with)\s+(.+?)(?:\s+(?:right )?now|\s+today)?\??$/i.exec(q);if(m){const words=m[1].toLowerCase();const sk=allSkills().find(s=>words.includes(s.n.toLowerCase())||s.n.toLowerCase().includes(words.trim()));if(sk){S.mpSel["sk_find_skills"]=[sk.id];SK.q.skills=[sk.id];SK.q.now=true;S.v.svc_skv=2;go("svc_skills");const r=routeBy({skills:[{id:sk.id,min:3}],limit:5,ai:true}).filter(c=>c.av.ok);say(q,{t:r.length?`${r.length} qualified people are working now for <b>${E(sk.n)}</b>: ${r.map(c=>`<b>${E(c.name)}</b> (${c.load}% load)`).join(", ")}.`:`Nobody at level 3 or higher in ${E(sk.n)} is working right now. ${SKILLSDB.qualified(sk.id,3).length} people are qualified in total.`,steps:["Looked up the skill in the taxonomy","Filtered level 3+ and not expired","Checked working hours, time off and holidays"]});return true}}
 if(/(assign|route).{0,20}(incident|ticket)|who should (take|get) (this|the) incident/i.test(q)){S.v.svc_ocv=3;go("svc_oncall");const r=simulate();say(q,{t:`For ${E((r.sv||{n:"the selected service"}).n)} ${OC.sim.prio}: rule <b>${r.rule?E(r.rule.n):"none"}</b> assigns to ${E(r.team||"the service desk")}; best claimer is <b>${r.cands[0]?E(r.cands[0].name):"nobody"}</b>.`,steps:["Matched assignment rules in order","Ranked people by skill, availability, load and language"]});return true}
 return false});
SEARCHX.push(()=>rotas().filter(R=>!R.gen).map(R=>({g:"On-call rotas",t:R.n,m:SCOPEN[R.scope]+" · "+nowOn(R,"Primary").join(", "),c:"--u3",f:()=>{go("svc_oncall");rotaDrawer(R.id)},k:"on call rota pager schedule "+R.target})));
SEARCHX.push(()=>allSkills().map(s=>({g:"Skills",t:s.n,m:s.cat+" · "+SKILLSDB.qualified(s.id,3).length+" qualified",c:"--s3",f:()=>{go("svc_skills");skillDrawer(s.id)},k:"skill who can do "+s.cat})));
