/* ---- R8 programmatic API (chat, flow, ITSM) ---- */
const findRota=x=>{if(!x)return null;const ro=rotas();return ro.find(R=>R.id===x)||ro.find(R=>R.target===x||R.n===x)||ro.find(R=>(R.n||"").toLowerCase().includes(String(x).toLowerCase()))||null};
OCX.whoIsOnCall=function(target,tier,t){const R=findRota(target);if(!R)return {rota:null,people:[],error:"No rota matches "+target};const tr=tier||"Primary";const tt=t!=null?toMs(t):NOW;return {rota:R.id,name:R.n,tier:tr,at:tt,people:at(R,tr,tt).map(x=>({who:x.who,kind:kindOf(x.who),via:x.lay,override:!!x.ov,onPto:!!(ptoHit(x.who,tt)&&ptoHit(x.who,tt).st==="approved")}))}};
OCX.assign=function(o){o=o||{};const R=findRota(o.rota||o.target);if(!R)return {ok:false,error:"No rota matches"};if(!o.who)return {ok:false,error:"Say who"};const from=o.from!=null?toMs(o.from):NOW,to=o.to!=null?toMs(o.to):from+DAY;const tier=o.tier||"Primary";const was=o.was||(at(R,tier,from)[0]||{}).who||"";const ov=addOv(R,tier,from,to,o.who,was,o.reason||"Assigned by request","override");return {ok:true,id:ov.id,rota:R.id,tier,who:o.who,was,from,to}};
OCX.swap=function(o){o=o||{};const R=findRota(o.rota||o.target);if(!R)return {ok:false,error:"No rota matches"};const w={id:"SW"+(OC.swaps.length+1),rota:R.id,tier:o.tier||"Primary",day:d0(o.day!=null?toMs(o.day):NOW+DAY),from:o.from,to:o.to,msg:o.msg||"",st:"Pending"};if(!w.from||!w.to)return {ok:false,error:"Need from and to"};OC.swaps.push(w);audit("swap requested",R.n+": "+w.from+" to "+w.to);if(o.approve){addOv(R,w.tier,w.day,w.day+DAY,w.to,w.from,"Swap approved","swap");w.st="Approved"}return {ok:true,id:w.id,status:w.st}};
WORK.push({kind:"Time off requests",tag:"PTO",fn:n=>allPto().filter(p=>p.who===n&&p.st!=="denied"&&pdate(p.to)>=d0(NOW)).slice(0,6).map(p=>({id:p.id,t:(p.type||"Time off")+(p.st==="pending"?" (awaiting approval)":""),sub:fd(pdate(p.from))+" to "+fd(pdate(p.to))+(p.note?" · "+p.note:""),due:fd(pdate(p.from)),st:p.st==="pending"?"warn":"info",hrs:0,go:()=>{S.v.svc_skv=5;go("svc_skills")}}))});
